import{_ as i,o as t,c as a,ag as s}from"./chunks/framework.gFULg22W.js";const u=JSON.parse('{"title":"Plugin Implementation Checklist","description":"","frontmatter":{},"headers":[],"relativePath":"dev/PLUGIN_CHECKLIST.md","filePath":"dev/PLUGIN_CHECKLIST.md"}'),n={name:"dev/PLUGIN_CHECKLIST.md"};function o(d,e,r,l,c,h){return t(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="plugin-implementation-checklist" tabindex="-1">Plugin Implementation Checklist <a class="header-anchor" href="#plugin-implementation-checklist" aria-label="Permalink to &quot;Plugin Implementation Checklist&quot;">​</a></h1><h2 id="shared-types-shared-types-ts" tabindex="-1">Shared Types (<code>shared/types.ts</code>) <a class="header-anchor" href="#shared-types-shared-types-ts" aria-label="Permalink to &quot;Shared Types (`shared/types.ts`)&quot;">​</a></h2><ul><li>[ ] Add <code>Kind&lt;NAME&gt; = &quot;&lt;name&gt;&quot;</code> to the <code>Kind</code> enum</li><li>[ ] Add <code>&lt;NAME&gt;Request</code> and <code>&lt;NAME&gt;Response</code> types</li><li>[ ] Add a row to the <code>KindTypes</code> table: <code>[Kind.&lt;NAME&gt;]: {request: &lt;NAME&gt;Request, response: &lt;NAME&gt;Response}</code></li><li>[ ] Source kinds: omit the <code>response</code> field (<code>RequestData</code>, <code>HistoryEntry</code>, <code>DraftableKind</code> and the db envelope derive from the table)</li></ul><h2 id="backend-main-database" tabindex="-1">Backend (<code>main/database/</code>) <a class="header-anchor" href="#backend-main-database" aria-label="Permalink to &quot;Backend (`main/database/`)&quot;">​</a></h2><ul><li>[ ] Create <code>&lt;name&gt;.ts</code> with <code>EmptyRequest: &lt;NAME&gt;Request</code> constant and <code>send(data: &lt;NAME&gt;Request): Promise&lt;&lt;NAME&gt;Response&gt;</code> (sync is fine for compute-only kinds)</li><li>[ ] No Electron imports in the plugin module (keeps it unit-testable)</li><li>[ ] Create <code>&lt;name&gt;.test.ts</code> with <code>bun:test</code>, mocking external dependencies via <code>mock.module</code></li><li>[ ] Exact equality assertions, not substring contains</li></ul><h2 id="dispatch-main-api-ts" tabindex="-1">Dispatch (<code>main/api.ts</code>) <a class="header-anchor" href="#dispatch-main-api-ts" aria-label="Permalink to &quot;Dispatch (`main/api.ts`)&quot;">​</a></h2><ul><li>[ ] Add case to <code>emptyRequestForKind(kind)</code> returning the empty request</li><li>[ ] Performable kind: add case to <code>Perform(id)</code> calling the plugin module&#39;s <code>send</code> and wrapping the result with the shared <code>historyEntry()</code> helper (the wire object is the shared <code>t.HistoryEntry</code>; history is renderer-side and transient)</li><li>[ ] Source kind: add a sub-API namespace instead (pattern: <code>export const GRPC</code> / <code>SQLSource</code> / <code>HTTPSource</code> / <code>MCP</code>)</li></ul><h2 id="ipc-surface" tabindex="-1">IPC Surface <a class="header-anchor" href="#ipc-surface" aria-label="Permalink to &quot;IPC Surface&quot;">​</a></h2><ul><li>[ ] <code>main.ts</code>: one <code>ipcMain.handle(&quot;&lt;Channel&gt;&quot;, ...)</code> per new channel</li><li>[ ] <code>preload.ts</code>: matching <code>ipcRenderer.invoke(&quot;&lt;Channel&gt;&quot;, ...)</code> entry in the <code>api: Api</code> object</li><li>[ ] <code>global.d.ts</code>: matching entry in the <code>Api</code> interface</li></ul><h2 id="frontend-renderer" tabindex="-1">Frontend (<code>renderer/</code>) <a class="header-anchor" href="#frontend-renderer" aria-label="Permalink to &quot;Frontend (`renderer/`)&quot;">​</a></h2><ul><li>[ ] Create <code>plugins/&lt;name&gt;/viewer.ts</code> — default export factory <code>(el, show_request, on: {update, send})</code> returning <code>{loaded, push_history_entry, unmount}</code></li><li>[ ] DOM with <code>m()</code> (<code>renderer/lib/utils.ts</code>), styles with <code>css</code>/<code>css.raw</code> (<code>renderer/lib/styles.ts</code>)</li><li>[ ] <code>signal&lt;T&gt;()</code> only for watched state</li><li>[ ] Errors rendered above main content</li><li>[ ] Debounce rapid updates (500ms) if the kind auto-computes</li><li>[ ] Clean up listeners/editors in <code>unmount()</code></li><li>[ ] Create <code>plugins/&lt;name&gt;/viewer.test.ts</code> (<code>bun:test</code> + <code>happy-dom</code>)</li></ul><h2 id="registration-renderer-plugins-name" tabindex="-1">Registration (<code>renderer/plugins/&lt;name&gt;/</code>) <a class="header-anchor" href="#registration-renderer-plugins-name" aria-label="Permalink to &quot;Registration (`renderer/plugins/&lt;name&gt;/`)&quot;">​</a></h2><ul><li>[ ] Wire the UI module into the plugin&#39;s <code>frame</code> hook: <ul><li>Performable: <code>frame: (args) =&gt; Request&lt;NAME&gt;(args.el, args.show_request, args.on);</code> plus <code>tabModifiers: [eyeTabModifier]</code> (shared eye toggle, <code>plugins/tab.ts</code>)</li><li>Source: <code>frame: (args) =&gt; Request&lt;NAME&gt;(args.el, {update: args.on.update});</code> with no <code>tabModifiers</code> (no editor pane to toggle)</li></ul></li><li>[ ] Source panes with fetched data: ship the viewer component (shared ones in <code>renderer/components/</code>, kind-specific ones colocated in <code>plugins/&lt;name&gt;/</code>) and expose it via the plugin&#39;s <code>viewers</code> hook (no <code>App.ts</code> edit — factories come from the registry)</li></ul><h2 id="plugin-renderer-plugins-every-kind" tabindex="-1">Plugin (<code>renderer/plugins/</code>, every kind) <a class="header-anchor" href="#plugin-renderer-plugins-every-kind" aria-label="Permalink to &quot;Plugin (`renderer/plugins/`, every kind)&quot;">​</a></h2><ul><li>[ ] Create <code>plugins/&lt;name&gt;/index.ts</code> exporting a <code>Plugin</code> (the UI factory lives in the sibling <code>viewer.ts</code>): <code>kind</code> + <code>frame</code> + <code>root</code> (invisible root item carrying the kind badge) + <code>viewers</code> (empty record when unused) for every kind; optional <code>tabModifiers</code> / <code>menuEntries</code> for tab and context-menu entries</li><li>[ ] Source kinds: implement the root item&#39;s listing in <code>&lt;name&gt;/item.ts</code> — a kind-private <code>createSourceCache(fetcher, errorTitle)</code> cache and a <code>root(id): Item</code> with <code>children: () =&gt; listChildren(cache, id, toItem)</code> (plus <code>loading</code>/<code>refresh</code>) thunks; per-item <code>onOpen</code> opens the viewer pane via <code>store.openViewer(title, componentType, state)</code></li><li>[ ] Item labels/badges are sync mappings over cached data — async work belongs to the fetcher</li><li>[ ] Add one line to <code>plugins</code> in <code>renderer/plugins/index.ts</code></li><li>[ ] No edits in <code>renderer/sidebar/</code> — tree children, click handling, tags, the Refresh entry, and staleness are registry-driven</li></ul><h2 id="database-main-db-ts" tabindex="-1">Database (<code>main/db.ts</code>) <a class="header-anchor" href="#database-main-db-ts" aria-label="Permalink to &quot;Database (`main/db.ts`)&quot;">​</a></h2><ul><li>[ ] No changes needed — the v1 migration switch only covers kinds that existed in v1 databases</li></ul><h2 id="post-implementation" tabindex="-1">Post-Implementation <a class="header-anchor" href="#post-implementation" aria-label="Permalink to &quot;Post-Implementation&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">             # unit + component tests</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:integration</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # INTEGRATION=1</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">               # lint + typecheck</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:e2e</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         # Playwright (renderer/e2e/)</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dist</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">             # package the app</span></span></code></pre></div><ul><li>[ ] Create a new request of the new kind</li><li>[ ] Perform it; response appears and lands in history</li><li>[ ] Restart the app; the request persists (<code>db.json</code>); the tab&#39;s history does not (renderer-side, transient)</li></ul><h2 id="quick-reference" tabindex="-1">Quick Reference <a class="header-anchor" href="#quick-reference" aria-label="Permalink to &quot;Quick Reference&quot;">​</a></h2><h3 id="plugin-types" tabindex="-1">Plugin Types <a class="header-anchor" href="#plugin-types" aria-label="Permalink to &quot;Plugin Types&quot;">​</a></h3><ul><li><strong>Performable kind</strong>: dispatched in <code>Perform</code>, result wrapped with the shared <code>historyEntry()</code> helper (wire object = <code>t.HistoryEntry</code>; history is renderer-side and transient; all current kinds: HTTP, SQL, GRPC, JQ, Redis, MD, DIFF)</li><li><strong>Source kind</strong>: no <code>Perform</code>; dedicated IPC sub-API queried on demand (SQLSource, HTTPSource, MCP); a <code>KindTypes</code> row without <code>response</code></li></ul><h3 id="key-decisions" tabindex="-1">Key Decisions <a class="header-anchor" href="#key-decisions" aria-label="Permalink to &quot;Key Decisions&quot;">​</a></h3><ol><li><strong>Performable or source?</strong> Has a one-shot execute action → <code>Perform</code>. Exposes browsing/querying of an external system → sub-API namespace.</li><li><strong>Defaults</strong>: provide sensible <code>EmptyRequest</code> — it&#39;s what users see on create</li><li><strong>Error display</strong>: above main content</li></ol><h3 id="full-guide" tabindex="-1">Full Guide <a class="header-anchor" href="#full-guide" aria-label="Permalink to &quot;Full Guide&quot;">​</a></h3><p>See <code>docs/dev/ADDING_NEW_PLUGINS.md</code> for a step-by-step walkthrough with code examples.</p>',27)])])}const g=i(n,[["render",o]]);export{u as __pageData,g as default};
